  "k_233a0e76b7b5": "Phân tích kết hợp chưa được tạo",
  "k_239d48dea044": "Tạo các ứng cử viên kịch bản",
  "k_23be11c82f2f": "Tái tạo phim để tạo phụ đề tiêu đề và thay thế trực tiếp video hiện đang xem.",
