  "k_341eddf3a668": "Đã chọn {p0} tác vụ, trong đó có {p1} đang chạy. Xác nhận xóa hàng loạt? Các tác vụ đang chạy sẽ bị buộc xóa và không thể khôi phục sau khi xóa.",
