  "k_50e078e7f961": "Đã chọn {p0} video",
  "k_5107f362963f": "Bảng phân cảnh được chọn cho {p0} đã được gửi và đang được xử lý đồng thời.",
  "k_5112ff1701be": "Thích hợp cho lợi ích về giá, giảm giá trong thời gian có hạn, điểm bán hàng hấp dẫn và cảm giác chuyển đổi thương mại điện tử mạnh mẽ hơn.",
  "k_5116727f3f58": "{p0} Nhiệm vụ video TikTok đã bị xóa theo đợt",
  "k_5120a5920064": "Vui lòng sao chép nội dung sau",
  "k_5149ae9c3017": "Hình ảnh tham khảo",
  "k_515bf9aa00f7": "Quá trình tạo sơ đồ đa góc sâu đã bắt đầu và DNA sản phẩm sẽ tự động được hoàn thành sau khi hoàn thành.",
  "k_5169b9ecce30": "Vui lòng nhập tên nhiệm vụ",
  "k_51991a5d111a": "thành công",
  "k_51b82e4e0729": "Bật phụ đề lồng tiếng",
  "k_51d8c0b478c8": "Phương pháp di chuyển:",
  "k_51dcc484cd16": "Sau khi tạo, nội dung tập lệnh hiện được sử dụng theo mặc định sẽ được hiển thị.",
  "k_51e5c2043884": "Số lần chụp trong 3 giây đầu tiên:",
  "k_52198bfdbee3": "Đang chờ kiểm tra đoạn",
  "k_523cdae527c8": "Không lưu được kích thước video, vui lòng thử lại.",
  "k_524ed3a52e93": "Người mẫu chưa đặt tên",
  "k_52b08e4bfe85": "Hình ảnh người mẫu {p0}",
  "k_533305d1af7c": "Gửi tác vụ đăng bài TikTok",
  "k_5349eb3e5762": "Chưa bắt đầu",
  "k_5384b125af47": "Phiên bản prompt đã được cập nhật. Phiên bản này sẽ không được áp dụng cho tác vụ cho đến khi nó được bật.",
  "k_53af67d6bcab": "vòng cổ",
  "k_53bbf3d53751": "Hiện tại không có hình ảnh nhận dạng hoặc bảng phân cảnh để hiển thị.",
  "k_53e2db70167f": "Không được chọn",
  "k_53e32830a538": "Tùy chọn",
  "k_5404b48fd379": "Mô tả liên kết hiện tại",
  "k_541ffadc27e2": "Không có bản xem trước video nào cho ảnh hiện tại và nó đã tự động chuyển sang bản xem trước ảnh có sẵn đầu tiên.",
  "k_54226874b463": "Sau khi được tạo từ bản vẽ tham chiếu, các tác vụ sẽ tự động xuất hiện ở đây.",
  "k_543156065601": "Thông báo lỗi giai đoạn không thể đọc được",
  "k_5439950aec35": "Ưu tiên mẫu gần nhất với kiểu sản phẩm, sau đó điều chỉnh kiểu chi tiết.",
  "k_5467275a0a9c": "bảng tham chiếu nhận dạng nằm giữa việc tạo kịch bản và thiết kế bảng phân cảnh, đồng thời hỗ trợ xem các prompt thực sự của quy trình chính.",
  "k_54984046a18e": "tóm tắt sản phẩm",
  "k_54a1d655a4e8": "Bản nháp/Tất cả nhiệm vụ",
  "k_54dd3a1f97df": "Tạo bản đồ đa góc sâu không thành công",
  "k_54f65b6b0c67": "bảng tham chiếu nhận dạng",
  "k_552647d32c4b": "Xem hình ảnh đa góc độ sâu",
  "k_556b607baa1d": "Thêm hình ảnh tham khảo",
  "k_55c2c7bc1576": "Kịch bản đề xuất đã được tạo và các bản vẽ nhận dạng và trang điểm đang được tạo tự động. Sau khi hoàn thành chúng ta sẽ bước vào thiết kế storyboard.",
  "k_55e7017a46b1": "Tạo hình ảnh",
  "k_55e931aa268f": "Tạo hình ảnh đa góc sâu chỉ dành cho sản phẩm từ hình ảnh tham chiếu, sau đó sử dụng hình ảnh đó làm tham chiếu chính cho hình ảnh sản phẩm.",
  "k_55f59bc2f0c3": "sao chép tất cả",
  "k_564b2da8f4cb": "chi tiết màu sắc",
  "k_565c73bcd588": "Trước tiên, vui lòng sửa các điều kiện tiên quyết dựa trên báo cáo lỗi ban đầu, sau đó tạo lại bảng phân cảnh hiện tại; nếu vẫn không thành công, hãy tiếp tục khắc phục sự cố dựa trên nhật ký chạy.",
  "k_56af34e7c5b6": "Thu gọn chỉnh sửa mẫu hiện tại",
  "k_57459c07244a": "sao chép prompt",
  "k_5767b8b4dc21": "Vui lòng chọn một sản phẩm từ thư viện sản phẩm trước.",
  "k_576ccdb1f1c7": "Cỡ chữ",
  "k_57c08c730a51": "Đang tạo",
  "k_580d9544c498": "nhóm tiêu đề",
  "k_582996bf3983": "Có thể tiếp tục tối ưu hóa",
  "k_58333db9405c": "nhập từ tập tin",
  "k_585767963b43": "Tự động thử lại {p0}/2, quá trình xử lý đã dừng",
