  "k_594249700590": "Đang chạy",
  "k_594fa15cbdaa": "Nếu hình ảnh sản phẩm thuần túy nền trắng vượt qua quá trình xác minh, bạn có thể tiếp tục tạo bảng vẽ phân tích đa góc.",
  "k_59588f0c7deb": "Tiếp tục hỏi thăm",
