  "k_6adb64a596d8": "Đăng lên Geelark",
  "k_6b6454d249df": "Vẽ lại, kéo hoặc thay đổi kích thước khu vực và bạn sẽ có thêm hai cơ hội để thử lại hình ảnh sau khi lưu.",
