  "k_6f941d67b36a": "Đang xóa...",
  "k_6fc7adf3f79a": "Việc tạo hình ảnh sản phẩm SKU {p0} không thành công, đang thử lại trong thời gian {p1}",
  "k_6fce855845a4": "Phân tích kịch bản đã hoàn tất. Vui lòng xác nhận rằng bạn đã chuẩn bị hình ảnh và mô hình tham khảo sản phẩm trước khi tiếp tục tạo kịch bản đề xuất.",
