  "k_7219420300d1": "Lưu và tái tạo",
  "k_721aa05e33b1": "Nhập từ mẫu",
  "k_721f98528d0c": "Mở tệp cầu nối siêu dữ liệu",
  "k_72f847dd1821": "Đầu tiên hãy chọn một video và nhập tiêu đề. Theo mặc định, chỉ tạo bản xem trước khung hình tĩnh nhẹ để giảm áp lực cho máy.",
