  "k_797b53b6badf": "Chuyển tiếp ngắn nhất",
  "k_79969aa2f219": "Ví dụ: khuyên tai cùng kiểu dáng với phần thân trên BGM 01",
  "k_79c74f41ca9e": "Đã tạo",
  "k_79d220908086": "Vui lòng chọn sản phẩm trước và nhấp vào \"Ràng buộc sản phẩm\" trước khi tiếp tục phân tích tập lệnh.",
  "k_79d85c0b1ac0": "xem kịch bản",
