  "k_7aaa2f87edf4": "Xuất cài đặt",
  "k_7ac7d958f450": "Các bản đồ đa góc sâu đang được tạo ra và DNA đang được hoàn thiện đồng thời",
  "k_7b060ff47103": "Sau khi thiết kế bảng phân cảnh hoàn tất, bạn sẽ vào khu vực làm việc của hàng đợi cảnh quay và xem kết quả được tạo theo thứ tự cảnh quay.",
