  "k_7c9474742cbe": "Hết thời gian chờ tiếp tục {p0}",
  "k_7ca26501dd28": "Chỉ có nhật ký chạy của tác vụ hiện tại được hiển thị ở đây.",
  "k_7cb2abcdb2fe": "Tiêu đề trưng bày sản phẩm",
  "k_7cc234042ef7": "Xác minh nền trắng",
  "k_7cc7f07a2c03": "trạng thái làm mới",
  "k_7cf5da95058a": "Mẫu cấu trúc phổ biến",
  "k_7d0694653644": "móc mở",
  "k_7d1e8e131273": "Tạo bảng tham chiếu nhận dạng",
  "k_7d3344fb9024": "Bối cảnh cuộc gọi trên đám mây: {p0}",
  "k_7d570b2ce11a": "Nó hạn chế hơn và phù hợp hơn với các sản phẩm chất lượng cao như đồ trang sức.",
  "k_7d6ec4c16873": "Thiết kế bảng phân cảnh hiện tại không còn dựa vào gói nhận dạng mô hình nữa. Vui lòng làm mới dự án và thử lại; nếu lỗi này vẫn xảy ra nghĩa là tiến trình chính vẫn còn bộ đệm cũ.",
  "k_7d77db14142f": "Duy trì LUT, nhãn dán, màu sắc và quy tắc đầu ra màn hình.",
  "k_7da807cf5fc2": "Kết quả đầu ra",
  "k_7db04ef30936": "Sau khi phân tích xong, các phân đoạn nội dung của video tham khảo sẽ hiển thị tại đây.",
  "k_7debf9cb0372": "cài đặt",
  "k_7df7698e6ee4": "Thời gian chờ đợi",
  "k_7e011d485110": "Lập kế hoạch hàng loạt không được kích hoạt",
  "k_7e1bc82ca787": "Không có nhãn dán",
  "k_7e33e07fd936": "tiêu đề phụ đề",
  "k_7e49a7c09a59": "taskId={p0}, gửi tác vụ đám mây",
  "k_7e4da0f6e774": "Xuất bản",
  "k_7e7f5d44c467": "Xuất bản không thành công",
  "k_7ebfc7c126cc": "Tổng quan về nhiệm vụ",
  "k_7f06ec27ae46": "Lựa chọn hiện tại",
  "k_7f36b37b3b4f": "Bóng mờ",
  "k_7f39a0d9ffad": "Cấu hình tiêu đề",
  "k_7f3a812a9479": "Xem nguồn tiêu chuẩn sản phẩm",
  "k_7f879a128512": "thất bại nặng nề",
  "k_7f87addec71e": "Âm thanh và hình ảnh",
  "k_7fb18dbeec08": "Chọn tỷ lệ video và kích thước cố định cho dự án này tại đây. XIBAPI sẽ sử dụng kích thước này không thay đổi khi gửi.",
  "k_7fb50c4c7d35": "Thiếu mã số nhiệm vụ {p0}",
  "k_802a9330758b": "Xóa lô nhiệm vụ này? Các tập tin đã tải xuống sẽ không tự động bị xóa.",
  "k_80333f7a00b2": "Kiểm soát truy cập đã được thông qua.",
  "k_809ff6b760b0": "Liên kết sản phẩm thành công.",
  "k_80be7ec3cff8": "Thêm vào mẫu",
  "k_80ee3f68f9ff": "Hiện tại không có thông số yêu cầu video nào để hiển thị.",
  "k_817af1870ca0": "Lưu cấu hình",
  "k_8185f33c5e78": "Đang viết lại...",
  "k_81897da3eeee": "nhiệm vụ đang tiến hành",
  "k_81918f2f9c19": "Sản phẩm chưa có tên",
  "k_81bbe719239f": "hành động chính",
  "k_81d2f34a4e28": "Video bảng phân cảnh hiện tại không còn dựa vào gói nhận dạng mô hình nữa. Vui lòng làm mới dự án và thử lại; nếu lỗi này vẫn xảy ra nghĩa là tiến trình chính vẫn còn bộ đệm cũ.",
  "k_81e993ba8045": "Đăng một nhiệm vụ",
  "k_8221bf9d729f": "tập lệnh mặc định",
  "k_8222dbd32528": "Thông tin meta cấu trúc phổ biến",
  "k_82232d270311": "Xuất cấu hình phân loại",
  "k_8285c0e23b75": "Một bản lồng tiếng trên mỗi dòng; --- có thể được sử dụng để phân tách các khối bản sao.",
  "k_829814eab6c6": "Số đầu sách hiện có:",
  "k_82a2909e8fe7": "{p0} kết quả đã được thêm vào nhóm xuất bản GeeLark.",
  "k_82b64f9960a8": "Chuyển tiếp",
  "k_82f516820cfe": "chất lượng",
  "k_83056258dd36": "Tạo quy trình",
  "k_83856208eaba": "hàng đợi nhiệm vụ",
  "k_83c5c36f37b0": "Bật phân loại màu cơ bản",
  "k_83cd75f8d97e": "Vui lòng nhập ít nhất một tiêu đề ngẫu nhiên.",
  "k_83e422384f7f": "có phụ đề",
  "k_83fb35964da6": "Thông số kỹ thuật cao nhất, phù hợp cho phim cuối cùng và màn hình đẹp",
  "k_842292abaac4": "{p0} Cập nhật",
  "k_84231f205c51": "chiều cao nhãn dán",
  "k_84ba3e6f5cfb": "nhóm tiêu đề ngẫu nhiên",
  "k_84bd36a8dda3": "Quy tắc sử dụng",
  "k_84e3802f60a7": "thời gian sáng tạo",
  "k_84fa79965540": "Nhập tiêu đề thống nhất",
  "k_84fcd70d4280": "Xóa",
  "k_851cdd609190": "đúng",
  "k_852b54e4bf6b": "Nhiệm vụ hàng đợi bị tạm dừng.",
  "k_8542beb99054": "Trạng thái xử lý",
  "k_8542c9c4c761": "Sau khi tải video tham khảo lên, hệ thống sẽ bắt đầu phân tích toàn bộ cấu trúc kịch bản.",
  "k_856480e2c5e1": "Đã lưu ghi chú.",
  "k_856af808c18a": "phân tích nhịp điệu",
  "k_856e405fcf39": "phong cách văn bản",
  "k_85736c94a112": "Bỏ qua giây mở đầu",
  "k_858dd89864ed": "Đã lưu sản phẩm",
  "k_862dcc21e281": "Xem trạng thái phát hành, lý do lỗi và kết quả khôi phục của các lần gửi gần đây.",
  "k_8689ec87d769": "Việc thu thập DNA sản phẩm không thành công",
  "k_86ba72ec4975": "Đợi quá trình phân tích tham chiếu hoàn tất",
  "k_86f9195e25e4": "Không được gắn nhãn",
  "k_8704840e5b6a": "Đang chờ video tham khảo",
  "k_875f93981c83": "Ống kính hiện tại không có taskId có thể được truy vấn và cần được tạo lại.",
  "k_878590943b3f": "Cấu hình hiện tại tạm thời",
  "k_878c3070dab2": "Đây là một bản xem trước video thực sự. Vui lòng làm mới thủ công sau khi sửa đổi tiêu đề hoặc kiểu để tránh bị treo trang thường xuyên.",
  "k_87c3e289a734": "Hiện tại không có hình ảnh tham khảo mô hình.",
  "k_8810731ffc4d": "Lựa chọn thư viện phim",
  "k_881de32901d5": "Xuất nhẹ, thích hợp để xem trước nhanh và xuất hàng loạt",
  "k_882d03bcf21c": "Đăng nội dung",
  "k_8831af0f9f89": "Trương)",
  "k_88481b5b3996": "{p0} đang được tạo lại, vui lòng không click lại.",
