  "k_960abbf38680": "Phụ đề được tạo cho video {p0}.",
  "k_961be9633733": "Sau khi ảnh hiện tại được tạo, bản xem trước lớn sẽ được hiển thị ở đây.",
  "k_96b029d1e14b": "phạm vi hiện tại",
