  "k_96fe1ffdfa89": "Áp dụng tập lệnh mặc định",
  "k_970dd864bf27": "Tất cả ứng dụng tiêu đề duy nhất",
  "k_970fb9cadf54": "Bắt đầu tạo tiêu đề sản phẩm và chuẩn bị hình ảnh sản phẩm",
  "k_971714bb3171": "Cau hinh nhac va am luong",
  "k_972994f9d113": "Tạo các video clip",
  "k_975c2f826062": "Phiên bản prompt hiện tại đã được bật. Các tác vụ cần thực hiện đã được đồng bộ hóa và phiên bản hiện tại sẽ được sử dụng khi thử lại tác vụ.",
  "k_97779e2726fc": "phong cách trực quan",
  "k_9788a29c8270": "yêu cầu",
  "k_97f500d19d6b": "tỷ lệ trộn",
  "k_981ab43e70c0": "Không có phản hồi từ đầu xa",
  "k_9827ba1c3829": "Truy vấn những storyboard còn dang dở... {p0}",
  "k_9828e4403587": "Ức chế dB",
  "k_98737ae281d9": "Cắt mật độ ống kính:",
  "k_98943466db66": "trạng thái phân tích",
  "k_98c1b3e34c1b": "ứng viên kịch bản",
  "k_98daa93daba9": "Có sự phân công lao động rõ ràng giữa hình ảnh sản phẩm và hình ảnh tham khảo, sản phẩm hiện tại được sử dụng làm nguồn thay thế duy nhất.",
  "k_98fd0cbd9c31": "Người mẫu",
  "k_99045f8ee1cd": "Tạo kết quả",
  "k_9910887469a0": "Đổi tên không thành công: {p0}",
  "k_9932971b51b4": "ID video tham khảo",
  "k_995c4ae82e7f": "Mẫu mã đẹp cho đơn hàng cao cấp",
  "k_9971be8eec5e": "Hiện tại không có số tác vụ từ xa",
  "k_998fd14c229b": "Sau khi thực hiện các thao tác như lưu, tạo và xuất trong plug-in, thông tin đang chạy mới nhất sẽ được hiển thị tại đây.",
  "k_99c39b2e596c": "Tác vụ \"{p0}\" đang chạy. Bạn có muốn xác nhận việc buộc xóa không? Điều này sẽ ngay lập tức xóa nó khỏi danh sách và dừng việc tiếp tục tự động cục bộ của tác vụ hiện tại. Nó không thể được phục hồi sau khi xóa.",
  "k_99e2de994bf1": "bắn từ trên cao",
  "k_99f31f48079b": "Kết quả hình ảnh và video có thể được xem trực tiếp",
  "k_9a0158b486f8": "Mặc định",
  "k_9a5425489f7f": "khối lượng TTS",
  "k_9ae39426bcca": "Hình ảnh sản phẩm",
  "k_9b53e535acea": "Số nhiệm vụ",
  "k_9b5c3c8f2f43": "Không đặt được bìa",
  "k_9b8309e541c9": "Sau khi hoàn thành video, MP4 có thể được tải xuống ngay lập tức thông qua tài khoản gốc và xuất hàng loạt được hỗ trợ trong thư viện.",
  "k_9b8782814cb7": "sự tò mò thúc đẩy",
  "k_9bac1ee6e12b": "Xem nhật ký gửi, trả về giao diện, chuyển giai đoạn và thông tin lỗi trong thời gian thực.",
  "k_9bd43c5d51d0": "Cookie tài khoản đã được mã hóa và lưu lại",
  "k_9c1d5accb8ef": "đoạn nội dung",
  "k_9c72a5cd5060": "Hướng dẫn tạo bảng tham chiếu nhận dạng được trả về bởi quy trình chính",
  "k_9c735206b1c6": "Thời gian phát hành dự kiến",
  "k_9ca6795dd07f": "Bắt đầu thêm phụ đề",
  "k_9ca96203a16a": "Độ nén cao hơn, xuất nhanh hơn",
  "k_9cb25b9d849e": "Đã chuyển sang chế độ mới, vui lòng tải lên video tham khảo mới.",
  "k_9ce7235cccfa": "Để được tối ưu hóa",
  "k_9ced4aad5c44": "Tạo lý do thất bại",
