  "k_d9c32a4c3dda": "không rõ",
  "k_da110e3d2cc6": "Có thể được tạo bằng AI trước rồi tinh chỉnh thủ công",
  "k_da4738cea064": "Tải",
  "k_da56d654f05a": "Phong cách ống kính:",
