  "k_dabe751bf59b": "Tái tạo bản đồ đa góc sâu",
  "k_dacdf7b9d85d": "tiến độ hàng loạt",
  "k_dae828fe4fb7": "Không.",
  "k_db062db6b3e9": "Vai trò ứng dụng",
  "k_db7edce09c55": "Vỏ điện thoại",
  "k_dbaa2b826577": "TikTok đang được tạo",
  "k_dbb37b794ab3": "Tạo tác vụ ({p0})",
  "k_dbc0b80307e9": "Không có câu chuyện đã mở khóa nào để tái tạo.",
  "k_dbd461ea511f": "Hình ảnh tham chiếu chính của sản phẩm Live Photo đã được cập nhật.",
  "k_dc0613dae17b": "đồ chơi",
  "k_dc203b880cda": "SKU {p0} Tạo tiêu đề không thành công, đang thử lại trong thời gian {p1}",
  "k_dc61f4f0fcef": "Mã số nhiệm vụ sắp được bổ sung",
  "k_dc7f89c5e018": "Tùy chọn bổ sung",
  "k_dc81cf3d2a9c": "Cau hinh thong tin va cach hien thi san pham",
  "k_dc8ac053db7a": "Quá trình tự động chạy",
  "k_dc9af490c182": "Phiên bản prompt V{p0} đã được tạo.",
  "k_dca303282767": "Chạy thủ công",
  "k_dcc251d28547": "Thiếu ràng buộc sản phẩm",
  "k_dcc4233255ab": "Vượt qua",
  "k_dce511108f5c": "Sơ đồ đa góc sâu + DNA sản phẩm",
  "k_dcf7ccbc9a09": "Di chuyển các nhiệm vụ {p0} tới nhóm được chỉ định.",
  "k_dd07e641ca66": "Cài đặt nâng cao",
  "k_dde1db57718c": "Đang xử lý...",
  "k_ddf6184c90e2": "Bánh xe {p0} chạy không tải liên tục",
  "k_de61aa8e1cbc": "Xem trước",
  "k_dea49eba6b37": "Lưu tài khoản",
  "k_deb4673d0f5d": "Tạo dựa trên đồ thị đa góc sâu",
  "k_ded698ae1e7e": "đầu ra",
  "k_df3ee667608c": "trái",
  "k_df429736ba90": "Chỉ hiển thị thành phần cục bộ và trạng thái xuất",
  "k_df4d23490b1b": "Đang chuẩn bị các tác vụ kết xuất hàng loạt...",
  "k_df5b3cd5d128": "Hình ảnh sản phẩm là nguồn gốc của thông tin chính và các hình ảnh đa góc độ sâu sắc được sử dụng để thúc đẩy sự đồng thuận về cấu trúc đa góc độ và hỗ trợ các mô tả prompt AI tiếp theo.",
  "k_df815f635a0d": "Chạy tự động từ giai đoạn hiện tại",
  "k_df905e7370e1": "Vui lòng đặt hình ảnh chính Live Photo trong danh sách sản phẩm trước, sau đó tạo tác vụ.",
  "k_dfebb5a654b9": "Tải hình ảnh sản phẩm lên trước, sau đó tiếp tục tạo hình ảnh đa góc sâu và các liên kết tiếp theo.",
  "k_dff042c80c67": "1. Trước tiên hãy chuẩn bị hình ảnh chính, hình ảnh chi tiết, hình ảnh sử dụng hoặc video thực tế của các sản phẩm tương tự trên trang sản phẩm.",
  "k_dff0626234ad": "Vui lòng chọn sản phẩm bạn muốn xuất trước",
  "k_dffd0cb74c18": "ID sản phẩm",
  "k_e007e1f404fc": "Không đổi tên được nhóm",
  "k_e019fc9d00d7": "Đã thu được DNA sản phẩm. Hệ thống sẽ phân tích trực tiếp hình ảnh sản phẩm hiện tại và kết quả hiện có, đồng thời sẽ không tạo lại hình ảnh đa góc sâu.",
  "k_e020ec7e37a3": "Tải xuống không thành công {p0}",
  "k_e0361480e3a5": "Bình luận",
  "k_e0461d4f37a4": "Hãy chọn nhiệm vụ cần di chuyển trước.",
  "k_e05805410133": "Cái kết nặng về doanh thu",
  "k_e0c29eaeb30b": "sao chép đường dẫn",
  "k_e0f3337364c8": "Phụ đề màu vàng",
  "k_e1033307612d": "Khu vực chính đã được cập nhật và hình ảnh đã được thử lại hai lần nữa.",
  "k_e11f729375a4": "Nó phù hợp hơn cho việc bán điểm và tiêu đề điểm lợi ích, đồng thời có cảm giác chuyển đổi mạnh mẽ hơn.",
  "k_e13a96ddf104": "Sao chép dưới dạng phiên bản mới",
  "k_e13bc676b50e": "Nếu phần giữa bằng phẳng, bạn có thể tăng trường bắn hoặc thay đổi chuyển động.",
  "k_e13c090fda1b": "Trước tiên, hãy định cấu hình ít nhất một tài khoản TikTok đã được kích hoạt",
  "k_e13e1d9b03d2": "Tạo trên đám mây",
  "k_e151dcc1a8d1": "Vui lòng chọn ít nhất một tác vụ có thể tạo phụ đề trước.",
  "k_e162faa756b1": "Mượt mà hơn và phù hợp làm xuất mặc định",
  "k_e1a420acee0f": "Quy trình thủ công",
  "k_e228b9e5d1d9": "Xác nhận xóa sản phẩm\"",
  "k_e24cb2a63e93": "Chọn khu vực chính và tạo lại nó",
  "k_e2627d4a83fc": "Tập trung vào sản phẩm là không đủ",
  "k_e29c909bf39f": "Nhật ký nhiệm vụ",
  "k_e2ceac018cc0": "Tổng thời lượng:",
  "k_e2d53a6d3a6a": "Thử lại",
  "k_e2dd92ea09a9": "Vui lòng thay đổi thành hình ảnh sản phẩm rõ ràng hơn, không bị cản trở hoặc xác nhận rằng dự án hiện tại đã được hoàn nguyên về hình ảnh ban đầu có sẵn trước khi thử lại.",
  "k_e2efc3482a19": "Hình ảnh sản phẩm và hình mẫu được hiển thị cạnh nhau",
  "k_e2f19210dbbf": "Đăng lại link chia sẻ: Close",
  "k_e2fd7c5ff973": "Bảo hiểm theo từng video",
  "k_e30d73d034d5": ", trọng tâm sản phẩm:",
  "k_e332ee564757": "Hoàn thành các thông tin sau và gửi nhiệm vụ xuất bản",
  "k_e33a423416a9": "Tái tạo lại bảng tham chiếu nhận dạng",
  "k_e33ea5f87622": "Thay thế ảnh hiện tại",
  "k_e370cdaf4557": "Hiện tại không có hình ảnh để hiển thị",
  "k_e3ba534bb0ab": "phiên bản prompt",
  "k_e3c71dbd0f6e": "Tổng số lần chụp:",
  "k_e48255e2ceca": "Sau khi chọn mô hình và sản phẩm thư viện sản phẩm, nhiều tập lệnh ứng viên sẽ được tạo.",
  "k_e4af82ef053a": "Tất cả các cảnh quay đều đã vượt qua cổng cuối cùng và có thể bước vào bộ phim cuối cùng.",
  "k_e4baf28f5192": "Bạn có thể tiếp tục hỏi:",
  "k_e528ba2c704f": "Đang chờ kết quả",
  "k_e53fc9418478": "Trạng thái thử lại",
  "k_e610551a276a": "Chưa có tài khoản nào được định cấu hình",
  "k_e63d8c73eb95": "Sản phẩm đã được lựa chọn nhưng chưa thực sự gắn kết với dự án; vui lòng hoàn thành phân tích video tham khảo trước khi đóng gói sản phẩm.",
  "k_e6bb01c6f837": "Nguồn mẫu: Mẫu cấu trúc phổ biến",
  "k_e6f568ddd540": "Tạo các tác vụ TikTok Image to Video theo đợt",
  "k_e712d79bc38b": "Cắt vào điểm đau",
  "k_e71c5a827969": "cái túi",
  "k_e7365a7456ac": "Chọn mô hình có thể tái sử dụng",
  "k_e75603d5853b": "Để bảo vệ tính bảo mật của tài khoản, các cookie đã lưu sẽ không được lặp lại. Hãy để trống phần này khi chỉ sửa đổi tên.",
  "k_e75aa98ee967": "Nhận...",
  "k_e7616a4eadcf": "Tăng cường điểm bán hàng",
  "k_e77f787d2a02": "Mở ảnh",
  "k_e7823e38b055": "Gửi nhiệm vụ đám mây",
  "k_e81f36aaa278": "Kiểm tra chất lượng và phiên bản prompt",
  "k_e877b7afbc3e": "Vui lòng nhập tên nhóm mới",
  "k_e88ab5ba616a": "đồng bộ",
  "k_e91365cf9ed9": "Có sẵn",
  "k_e95355896fde": "lắc lư nhẹ",
