  "k_ed70ccdd3b92": "Tạo tập lệnh ứng viên",
  "k_ed96bfd66e94": "Xem trước prompt từ bảng tham chiếu nhận dạng",
  "k_edebd6eca212": "Vui lòng chọn ít nhất một nhiệm vụ đã hoàn thành trước.",
  "k_ee3f5a9629c5": "Còn những ảnh chưa qua cổng cuối cùng, hãy xử lý trước khi ghép.",
  "k_ee6d8a648daa": "Sử dụng ứng cử viên âm nhạc địa phương",
  "k_ee7023263319": "Quay trở lại thị trường plug-in",
  "k_ee92e0cae58d": "Đây là prompt thực tế được truyền cho mô hình",
  "k_ee9684155466": "Việc chỉnh sửa được khôi phục về không gian làm việc rộng ở đây, không còn bị ép vào cột hẹp bên phải.",
  "k_eebeed545caf": "Kích hoạt nhiễu loạn màu sắc",
