  "k_f0c424a3130e": "Vui lòng nhập SKU",
  "k_f0effeae0cf7": "Gửi tới Tạo ý tưởng TikTok",
  "k_f0f714654722": "Xem trước phim cuối cùng",
  "k_f109b5c73a8f": "Phim sắp phát hành",
  "k_f14e1e658c86": "Kịch bản:",
  "k_f164b8f467c2": "Hệ thống đang xác minh hình ảnh sản phẩm thuần túy nền trắng, vui lòng làm mới sau.",
  "k_f16863b53694": "Tái tạo mục bị lỗi {p0}",
  "k_f17b90b1c5e4": "Sân bóng đá",
  "k_f1c3fed4770a": "Quy tắc phù hợp",
  "k_f20d9f75fb6a": "Hình ảnh tham khảo:",
  "k_f2190e39fc99": "Hoặc bấm vào để tải ảnh lên",
  "k_f25fdbd62c22": "Giao diện chính thức xử lý tự động",
