  "k_f2b41b9c6a9c": "Tạo phụ đề tiêu đề cho từng video và thay thế trực tiếp video hiện đang xem.",
  "k_f2d06a139c22": "{p0} vị trí có mục đích cố định, không phải xếp hạng",
