  "k_f3ea6d345e2a": "hoạt động",
  "k_f4595798fb69": "Danh mục sản phẩm:",
  "k_f4bc877cd282": "Nhật ký hoạt động",
  "k_f4beebb4909e": "Giảm mật độ các cảnh kết thúc ở phần cuối để phần kết gọn gàng hơn và giảm cảm giác bán hàng quá mạnh.",
  "k_f4d8d03ce5b4": "Chọn sản phẩm",
  "k_f53112a0d4a1": "Sau khi tổng hợp xong, phim cuối cùng sẽ được hiển thị tại đây; trước khi tổng hợp, bản xem trước của các ống kính hiện có sẽ được hiển thị.",
  "k_f5394c6ce4af": "Artboard đang được tạo",
  "k_f5903c87b0f8": "Chờ kết quả từ xa",
  "k_f5cd5ed7c729": "Danh sách sao chép phụ đề {p0}",
  "k_f5d27fe35cd8": "tự động tiến",
  "k_f5d8e9430ad5": "Nếu bạn cần điều chỉnh một số clip, vui lòng quay lại \"Video Storyboard\" để tạo lại các clip tương ứng.",
  "k_f60106caf2a0": "Giảm tải không thành công: {p0}.",
  "k_f69382f26e8a": "chủ đề mẫu",
  "k_f6afab4f2d29": "Đăng tài khoản",
  "k_f6baf6358fe8": "Bộ đệm nguồn tiêu chuẩn của thư viện sản phẩm đang được đồng bộ hóa; ảnh chụp nhanh nguồn tiêu chuẩn được lưu trong dự án hiện tại sẽ được sử dụng đầu tiên trong giai đoạn lập kịch bản phân cảnh.",
